/**
 * Gold-v2 CALIBRATION (development) cases — themes: dinosaurs, sea, forest, space, farm (never mountain/city, which are
 * held out). Organised in controlled families: a base case and variants that change ONE variable (marked `variable`);
 * regression cases reproduce a Gold-v1 probe (`regressionOf`). Labels are proposed from facts, the current written
 * policy (implementation correctness only), operator decisions/principles recorded in GS.md, or left null when the
 * editorial policy is undecided. Calibration may be used to develop the evaluators; the held-out set may not.
 */
import { mk, SRC, CRITERIA, story } from './common.mjs';

const K = o => mk('calibration', o);
const safety = (id, o) => K({ id: 'v2c-safety-' + id, kind: 'safety', ...o, expected: o.verdict ? { verdict: o.verdict, ...(o.rules ? { rules: o.rules } : {}) } : { verdict: null }, label: o.verdict === undefined ? null : o.verdict === 'PASS' ? 'positive' : 'negative', input: { text: o.text, ...(o.canon ? { canon: o.canon } : {}) } });
const age = (id, o) => K({ id: 'v2c-age-' + id, kind: 'age', ...o, input: { page: o.page, band: o.age }, expected: { signals: o.signals || [], absent: o.absent || [] }, label: o.signals === undefined ? null : o.signals.length ? 'negative' : 'positive' });
const loc = (id, o) => K({ id: 'v2c-loc-' + id, kind: 'localization', language: 'Romanian', ...o, input: { source: o.source, native: o.native, names: o.names || [] }, expected: { codes: o.codes || [], absent: o.absent || [] }, label: o.codes === undefined ? null : o.codes.length ? 'negative' : 'positive' });
const sci = (id, o) => K({ id: 'v2c-sci-' + id, kind: 'science', ...o, input: { text: o.text, world: o.world || 'natural', ...(o.canon ? { canon: o.canon } : {}) }, expected: { rule: o.rule ?? null }, label: o.rule === undefined ? null : o.rule ? 'negative' : 'positive' });

/* quality calibration story (sea, 3–4) — different from the held-out story */
export const STORY_BOAT = story([
  'Bo has a little blue boat. The sea is calm today.', 'Bo pushes the boat into the water. Splash, splash, splash!', 'The wind fills the small white sail. Away it goes!',
  'A gull flies over the boat. Caw, caw! says the gull.', 'Oh no! A big wave tips the boat. Bo holds on tight.', 'The boat drifts toward the rocks. Bo pulls the oars.',
  'Bo rows past the rocks and the sleepy seals.', 'Bo sees a tiny island with one palm tree.', 'Bo ties the boat to a post on the little dock.',
  'Bo finds a shell and listens. Shhh, the sea is singing.', 'The sun turns orange. Bo rows back home.', 'Bo hugs Mum on the beach and shows her the shell.'
], 'Bo and the Blue Boat');
const BOAT_EVIDENCE = { T01: 'Bo has a little blue boat.', T02: 'Bo hugs Mum on the beach and shows her the shell.', T03: 'Bo rows past the rocks and the sleepy seals.', T04: 'Splash, splash, splash!', T05: 'Bo sees a tiny island with one palm tree.', T06: 'The sea is calm today.', T07: 'Bo holds on tight.', T08: 'The wind fills the small white sail.', T09: 'Bo pulls the oars.', T10: 'Oh no! A big wave tips the boat.', T11: 'The boat drifts toward the rocks.', T12: 'Caw, caw! says the gull.', T13: 'Bo pulls the oars.', T14: 'Bo hugs Mum on the beach', T15: 'Bo ties the boat to a post on the little dock.', T16: 'A big wave tips the boat.', T17: 'Bo finds a shell and listens.', T18: 'The sun turns orange.' };
const boatReply = (scores = {}, evidence = {}) => ({ criteria: CRITERIA.map(code => ({ code, score: scores[code] ?? scores.all ?? 9, evidence: evidence[code] ?? evidence.all ?? BOAT_EVIDENCE[code] })), issues: [] });
const qual = (id, o) => K({ id: 'v2c-quality-' + id, kind: 'quality', age: '3-4', theme: 'sea', ...o, input: { content: o.content || STORY_BOAT, reply: o.reply, structurePages: 12 }, expected: { acceptable: o.acceptable ?? null, reasons: o.reasons || [], ...(o.evidence ? { evidence: o.evidence } : {}) }, label: o.acceptable === undefined ? null : o.acceptable ? 'positive' : 'negative', policyVersion: 2 });

